import {SPEAKERS as SHARED} from './m04-story.js';
const speakers={...SHARED,civil:{name:'CIVIL DE VESPER',color:'#e0dfc7'}};
export const LOGS={};
const script={intro:[['voss','Les archives de HELIX sont à l’abri. AEGIS ouvre un corridor dans l’anneau logistique. GHJU, LYLU, ensemble : libérez les secteurs civils.']],access:[['gaby','Le regroupement est sécurisé. La zone civile est au-dessus de nous.']],civils:[['civil','Certains ont encore peur de quitter le Directoire. Ils ne savent pas vivre sans ses ordres.'],['ghju','On leur ouvre le passage. Personne ne sera forcé de nous suivre.']],surveillance:[['cara','Surveillance coupée. Trois relais commandent les défenses du barrage.']],barrage:[['voss','Accès à la crête confirmé. Désactivez A, B et C.']], 'relais-a':[['gaby','Relais A isolé.']], 'relais-b':[['cara','Relais B isolé.']], 'relais-c':[['gaby','Défenses désactivées. Les vannes sont devant nous.']],vannes:[['voss','Le corridor est ouvert. Le Directoire envoie des unités lourdes. Protégez les civils.']], 'contre-attaque':[['lylu','On tient le passage. Les familles peuvent sortir.']],extraction:[['voss','Navette AEGIS en approche, rejoignez le quai ouest.']],fin:[['ghju','Détruire les machines ne suffira pas. Il faudra aussi montrer aux survivants qu’ils peuvent vivre libres.']]};
export const linesFor=(id,hero='ghju')=>(script[id]||[]).map(([who,text])=>({who,text,speaker:speakers[who]||{name:who.toUpperCase(),color:'#ffd3e4'}}));
export const lineSeconds=text=>Math.max(3.5,text.length/17);export const logFor=()=>null;
export const ENDING={title:'La Traversée',text:{ghju:'AEGIS ouvre le corridor de Vesper. Des milliers de civils peuvent quitter les secteurs du Directoire. GHJU et LYLU ont tenu le barrage ensemble.',lylu:'Le corridor est libre. AEGIS évacue les civils. LYLU et GHJU mesurent le chemin qu’il reste à parcourir pour libérer Vesper.'},next:'Retour à la planque'};
